const GALAXY_GEN = 4;
// 銀河の版 3 から、銀河面から ±THIN_SLAB 光年の板の中の星だけを使う (星の表は ±17 光年の板。版 2 までのセーブはそのまま読む)。
// 星が多すぎて地図を操作できなかったため (ユーザーの指示)
const THIN_SLAB = 2;
